def solve(grid):
    if not grid:
        return 0
    rows = len(grid)

    def is_land(v):
        if v is None or v is False:
            return False
        if isinstance(v, str):
            return v.strip() not in ('', '0')
        return bool(v)

    def row_len(r):
        row = grid[r]
        try:
            return len(row)
        except TypeError:
            return 0

    visited = set()
    count = 0
    for r in range(rows):
        for c in range(row_len(r)):
            if is_land(grid[r][c]) and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < row_len(nr) \
                                and is_land(grid[nr][nc]) and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))
    return count

